-- ============================================================================
-- Fase 6 - Facturacion (PostgreSQL)
-- Esquema destino: "OLTP"
--
-- Generado por oltp/datos_prueba/generar_datos.py.
-- No editar a mano: los cambios deben hacerse en el generador.
--
-- Contenido: 300 facturas y 300 detalles (una por servicio).
-- Estados: 180 pagadas (36 con pago parcial), 75 pendientes y 45 vencidas.
-- La fecha de emision es la fecha del servicio y el vencimiento
-- es la emision + 30 dias.
-- La cobertura usa la poliza principal vigente; si no cubre la
-- categoria, intenta la secundaria. Sin poliza el paciente paga todo.
--
-- Requiere: 01_catalogos.sql, 02_maestros.sql, 03_polizas.sql,
--           04_ingresos_ocupaciones.sql y 05_servicios.sql.
-- ============================================================================

SET search_path TO "OLTP";

TRUNCATE TABLE "OLTP".FACTURA, "OLTP".FACTURA_DETALLE CASCADE;

-- ============================================================================
-- Facturas
-- ============================================================================

-- ============================================================================
-- Detalle de factura (un servicio por linea)
-- ============================================================================

-- ============================================================================
-- Autovalidacion de la fase
-- ============================================================================
DO $$
DECLARE
	v_filas INTEGER;
BEGIN
	SELECT count(*) INTO v_filas FROM FACTURA;
	IF v_filas < 200 THEN
		RAISE EXCEPTION 'Se esperaban al menos 200 facturas y hay %', v_filas;
	END IF;

	-- Una factura por servicio.
	SELECT count(*) INTO v_filas FROM FACTURA;
	IF v_filas <> (SELECT count(*) FROM REALIZA)
	            + (SELECT count(*) FROM PRESCRIBE)
	            + (SELECT count(*) FROM PRACTICA) THEN
		RAISE EXCEPTION 'La cantidad de facturas no coincide con los servicios: %', v_filas;
	END IF;

	SELECT count(*) INTO v_filas FROM FACTURA f
	WHERE (SELECT count(*) FROM FACTURA_DETALLE d
	       WHERE d.ID_FACTURA = f.ID_FACTURA) <> 1;
	IF v_filas > 0 THEN
		RAISE EXCEPTION 'Hay facturas sin exactamente un detalle: %', v_filas;
	END IF;

	SELECT count(*) INTO v_filas FROM REALIZA r
	WHERE NOT EXISTS (
		SELECT 1 FROM FACTURA_DETALLE d WHERE d.ID_REALIZA = r.ID_REALIZA
	);
	IF v_filas > 0 THEN
		RAISE EXCEPTION 'Hay diagnosticos sin factura: %', v_filas;
	END IF;

	SELECT count(*) INTO v_filas FROM PRESCRIBE p
	WHERE NOT EXISTS (
		SELECT 1 FROM FACTURA_DETALLE d WHERE d.ID_PRESCRIPCION = p.ID_PRESCRIPCION
	);
	IF v_filas > 0 THEN
		RAISE EXCEPTION 'Hay prescripciones sin factura: %', v_filas;
	END IF;

	SELECT count(*) INTO v_filas FROM PRACTICA p
	WHERE NOT EXISTS (
		SELECT 1 FROM FACTURA_DETALLE d WHERE d.ID_PRACTICA = p.ID_PRACTICA
	);
	IF v_filas > 0 THEN
		RAISE EXCEPTION 'Hay intervenciones sin factura: %', v_filas;
	END IF;

	-- El detalle y la factura describen el mismo servicio y el mismo monto.
	SELECT count(*) INTO v_filas
	FROM FACTURA_DETALLE d
	JOIN FACTURA f ON f.ID_FACTURA = d.ID_FACTURA
	LEFT JOIN REALIZA r ON r.ID_REALIZA = d.ID_REALIZA
	LEFT JOIN PRESCRIBE p ON p.ID_PRESCRIPCION = d.ID_PRESCRIPCION
	LEFT JOIN PRACTICA pr ON pr.ID_PRACTICA = d.ID_PRACTICA
	WHERE d.F_SERVICIO <> f.F_EMISION
	   OR d.MONTO <> f.MONTO_TOTAL
	   OR (d.ID_REALIZA IS NOT NULL AND d.ID_TIPO_SERVICIO <> 1)
	   OR (d.ID_PRESCRIPCION IS NOT NULL AND d.ID_TIPO_SERVICIO <> 2)
	   OR (d.ID_PRACTICA IS NOT NULL AND d.ID_TIPO_SERVICIO <> 3)
	   OR (r.ID_REALIZA IS NOT NULL
	       AND (r.NUMBER_INGRESO <> f.NUMBER_INGRESO OR r.CI_PAC <> f.CI_PAC))
	   OR (p.ID_PRESCRIPCION IS NOT NULL
	       AND (p.NUMBER_INGRESO <> f.NUMBER_INGRESO OR p.CI_PAC <> f.CI_PAC))
	   OR (pr.ID_PRACTICA IS NOT NULL
	       AND (pr.NUMBER_INGRESO <> f.NUMBER_INGRESO OR pr.CI_PAC <> f.CI_PAC));
	IF v_filas > 0 THEN
		RAISE EXCEPTION 'Hay detalles incoherentes con su factura: %', v_filas;
	END IF;

	SELECT count(*) INTO v_filas FROM FACTURA
	WHERE MONTO_CUBIERTO + MONTO_PACIENTE <> MONTO_TOTAL;
	IF v_filas > 0 THEN
		RAISE EXCEPTION 'Hay facturas con montos incoherentes: %', v_filas;
	END IF;

	SELECT count(*) INTO v_filas FROM FACTURA
	WHERE (MONTO_CUBIERTO > 0
	       AND (TIPO_CLIENTE <> 'ASEGURADORA'
	            OR ID_POLIZA IS NULL OR ID_ASEGURADORA IS NULL))
	   OR (MONTO_CUBIERTO = 0 AND TIPO_CLIENTE <> 'PACIENTE');
	IF v_filas > 0 THEN
		RAISE EXCEPTION 'Hay facturas con tipo de cliente incoherente: %', v_filas;
	END IF;

	SELECT count(*) INTO v_filas FROM FACTURA
	WHERE F_VENCIMIENTO <> F_EMISION + 30;
	IF v_filas > 0 THEN
		RAISE EXCEPTION 'Hay facturas con vencimiento distinto de emision + 30: %', v_filas;
	END IF;

	-- La poliza usada debe cubrir la categoria del servicio y estar vigente.
	SELECT count(*) INTO v_filas
	FROM FACTURA f
	JOIN FACTURA_DETALLE d ON d.ID_FACTURA = f.ID_FACTURA
	JOIN TIPO_SERVICIO ts ON ts.ID_TIPO_SERVICIO = d.ID_TIPO_SERVICIO
	JOIN POLIZA p ON p.ID_POLIZA = f.ID_POLIZA
	WHERE NOT p.APROBADA
	   OR f.MONTO_CUBIERTO > p.COBERTURA
	   OR f.F_EMISION < p.F_DESDE
	   OR (p.F_HASTA IS NOT NULL AND f.F_EMISION > p.F_HASTA)
	   OR (ts.CATEGORIA_POLIZA = 'EXAMENES' AND NOT p.EXAMENES)
	   OR (ts.CATEGORIA_POLIZA = 'HOSPITALIZACION' AND NOT p.HOSPITALIZACION)
	   OR (ts.CATEGORIA_POLIZA = 'CIRUGIA' AND NOT p.CIRUGIA);
	IF v_filas > 0 THEN
		RAISE EXCEPTION 'Hay facturas con una poliza que no cubre el servicio: %', v_filas;
	END IF;

	SELECT count(*) INTO v_filas FROM FACTURA
	WHERE ID_POLIZA IS NULL AND MONTO_CUBIERTO <> 0;
	IF v_filas > 0 THEN
		RAISE EXCEPTION 'Hay facturas sin poliza con monto cubierto: %', v_filas;
	END IF;

	-- Pagadas: con fecha y monto de pago, dentro del corte.
	SELECT count(*) INTO v_filas FROM FACTURA
	WHERE ID_ESTADO = 1
	  AND (F_PAGO IS NULL OR MONTO_PAGADO IS NULL
	       OR F_PAGO < F_EMISION OR F_PAGO > DATE '2026-10-31'
	       OR F_PAGO - F_EMISION < 5 OR F_PAGO - F_EMISION > 90
	       OR MONTO_PAGADO <= 0);
	IF v_filas > 0 THEN
		RAISE EXCEPTION 'Hay facturas pagadas sin pago valido: %', v_filas;
	END IF;

	-- Pendientes y vencidas: impagas.
	SELECT count(*) INTO v_filas FROM FACTURA
	WHERE ID_ESTADO IN (2, 3)
	  AND (F_PAGO IS NOT NULL OR MONTO_PAGADO IS NOT NULL);
	IF v_filas > 0 THEN
		RAISE EXCEPTION 'Hay facturas impagas con datos de pago: %', v_filas;
	END IF;

	SELECT count(*) INTO v_filas FROM FACTURA
	WHERE ID_ESTADO = 2
	  AND (F_EMISION < DATE '2026-08-01' OR F_EMISION > DATE '2026-10-31');
	IF v_filas > 0 THEN
		RAISE EXCEPTION 'Hay facturas pendientes fuera del cobro reciente: %', v_filas;
	END IF;

	SELECT count(*) INTO v_filas FROM FACTURA
	WHERE ID_ESTADO = 3 AND F_VENCIMIENTO >= DATE '2026-09-01';
	IF v_filas > 0 THEN
		RAISE EXCEPTION 'Hay facturas vencidas con mora de 60 dias o menos: %', v_filas;
	END IF;

	SELECT count(*) INTO v_filas FROM FACTURA WHERE ID_ESTADO = 1;
	IF v_filas < 150 THEN
		RAISE EXCEPTION 'Se esperaban al menos 150 facturas pagadas y hay %', v_filas;
	END IF;

	SELECT count(*) INTO v_filas FROM FACTURA WHERE ID_ESTADO = 2;
	IF v_filas < 50 THEN
		RAISE EXCEPTION 'Se esperaban al menos 50 facturas pendientes y hay %', v_filas;
	END IF;

	SELECT count(*) INTO v_filas FROM FACTURA WHERE ID_ESTADO = 3;
	IF v_filas < 30 THEN
		RAISE EXCEPTION 'Se esperaban al menos 30 facturas vencidas y hay %', v_filas;
	END IF;

	-- La mayoria de los pagos son totales, pero debe haber algunos parciales.
	SELECT count(*) INTO v_filas FROM FACTURA
	WHERE ID_ESTADO = 1 AND MONTO_PAGADO < MONTO_TOTAL;
	IF v_filas = 0 THEN
		RAISE EXCEPTION 'No hay facturas pagadas con pago parcial';
	END IF;
	IF v_filas >= (SELECT count(*) / 2 FROM FACTURA WHERE ID_ESTADO = 1) THEN
		RAISE EXCEPTION 'Demasiadas facturas pagadas con pago parcial: %', v_filas;
	END IF;
END;
$$;
